// --- Built-in Content Library ---
// Ready-made models, textures and sounds (assets/showcase, generated by
// tools/showcase-assets.js) that any project can use, so a blank project is
// not limited to primitive shapes. Items load on demand and become ordinary
// project assets: they save, undo, export and prefab like imported ones.
// Must stay before the boot module (Start Blank adds the default character).

var CONTENT_LIBRARY_BASE = '../assets/showcase/';
var contentLibraryManifest = null;
var contentLibraryManifestPromise = null;
var contentLibraryCache = new Map();
var CONTENT_LIBRARY_GROUPS = [
  { id: 'nature', label: 'Nature', icon: '🌲', match: (m) => /tree|bush|grass|rock|stump|cliff/.test(m.key) },
  { id: 'fantasy', label: 'Ruins & fantasy', icon: '🏛', match: (m) => m.file.startsWith('fantasy/') },
  { id: 'scifi', label: 'Sci-fi', icon: '🛰', match: (m) => m.file.startsWith('scifi/') },
  { id: 'combat', label: 'Combat', icon: '⚔', match: (m) => m.file.startsWith('combat/') },
  { id: 'characters', label: 'Characters & vehicles', icon: '🧍', match: (m) => m.file.startsWith('characters/') || m.file.startsWith('vehicles/') },
];
function contentLibraryGroup(model) {
  return CONTENT_LIBRARY_GROUPS.find((group) => group.match(model)) || CONTENT_LIBRARY_GROUPS[1];
}
function contentLibraryLabel(key) {
  return key.replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}
function loadContentLibraryManifest() {
  if (contentLibraryManifest) return Promise.resolve(contentLibraryManifest);
  if (!contentLibraryManifestPromise) {
    contentLibraryManifestPromise = fetch(CONTENT_LIBRARY_BASE + 'manifest.json', { cache: 'no-cache' })
      .then((response) => { if (!response.ok) throw new Error('HTTP ' + response.status); return response.json(); })
      .then((manifest) => {
        // Game-specific landmark models stay with their example games.
        manifest.meshes = (manifest.meshes || []).filter((m) => !m.key.startsWith('hero-'));
        contentLibraryManifest = manifest;
        return manifest;
      })
      .catch((error) => { contentLibraryManifestPromise = null; throw error; });
  }
  return contentLibraryManifestPromise;
}
function fetchContentLibraryFile(file, kind) {
  const key = kind + ':' + file;
  if (!contentLibraryCache.has(key)) {
    const request = fetch(CONTENT_LIBRARY_BASE + file).then((response) => {
      if (!response.ok) throw new Error('HTTP ' + response.status + ' for ' + file);
      if (kind === 'json') return response.json();
      return response.blob().then((blob) => new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(new Error('Could not read ' + file));
        reader.readAsDataURL(blob);
      }));
    });
    request.catch(() => contentLibraryCache.delete(key));
    contentLibraryCache.set(key, request);
  }
  return contentLibraryCache.get(key);
}
// Adds one library model (and its texture) to the project, without placing it.
async function ensureContentLibraryModel(key) {
  const manifest = await loadContentLibraryManifest();
  const entry = manifest.meshes.find((m) => m.key === key);
  if (!entry) throw new Error('Unknown library model: ' + key);
  const record = findAssetById(entry.id) ? null : await fetchContentLibraryFile(entry.file, 'json');
  const textureId = record ? record.textureAssetId : findAssetById(entry.id).textureAssetId;
  let textureRecord = null;
  if (textureId && !findTextureAssetById(textureId)) {
    const textureEntry = (manifest.textures || []).find((t) => t.id === textureId);
    if (textureEntry) textureRecord = { id: textureEntry.id, name: textureEntry.key, dataURL: await fetchContentLibraryFile(textureEntry.file, 'dataurl'), sourceFilename: textureEntry.file.split('/').pop(), folder: 'Content Library' };
  }
  return { entry, record, textureRecord };
}
async function addContentLibraryModel(key) {
  if (playMode) { showStatus('Stop Play before adding library content'); return null; }
  let prepared;
  try { prepared = await ensureContentLibraryModel(key); }
  catch (error) { showStatus('Content Library unavailable: ' + error.message); return null; }
  if (playMode) return null;
  pushUndo();
  if (prepared.textureRecord) loadTextureAssets([prepared.textureRecord]);
  if (prepared.record) loadAssets([prepared.record]);
  const asset = findAssetById(prepared.entry.id);
  if (!asset) { showStatus('Library model could not be added'); return null; }
  const target = app.camera.target || new Opus.Vec3(0, 0, 0);
  const item = placeAssetInstance(asset, new Opus.Vec3(target.x, 0, target.z), false);
  if (item && !item.name) { item.name = contentLibraryLabel(key); renderSceneList(); }
  if (typeof refreshAssetDiscovery === 'function') refreshAssetDiscovery();
  showStatus(`Added ${contentLibraryLabel(key)} · Undo removes it`);
  return item;
}
async function addContentLibrarySound(key) {
  try {
    const manifest = await loadContentLibraryManifest();
    const entry = (manifest.audio || []).find((a) => a.key === key);
    if (!entry) throw new Error('Unknown library sound: ' + key);
    if (findAudioAssetById(entry.id)) { showStatus(`${contentLibraryLabel(key)} is already in this project`); return; }
    const dataURL = await fetchContentLibraryFile(entry.file, 'dataurl');
    if (playMode) { showStatus('Stop Play before adding library content'); return; }
    pushUndo();
    loadAudioAssets([{ id: entry.id, name: entry.key, dataURL, sourceFilename: entry.file.split('/').pop(), folder: 'Content Library' }]);
    if (typeof refreshAssetDiscovery === 'function') refreshAssetDiscovery();
    showStatus(`Added sound ${contentLibraryLabel(key)} · choose it in Play Sound actions`);
  } catch (error) { showStatus('Content Library unavailable: ' + error.message); }
}
function previewContentLibrarySound(key) {
  const entry = contentLibraryManifest && (contentLibraryManifest.audio || []).find((a) => a.key === key);
  if (!entry) return;
  try { const audio = new Audio(CONTENT_LIBRARY_BASE + entry.file); audio.volume = 0.6; audio.play().catch(() => {}); } catch (error) { /* preview only */ }
}

// --- Assets tab section ---
function ensureContentLibrarySection() {
  let section = document.getElementById('content-library');
  if (section) return section;
  const tab = document.getElementById('left-tab-assets');
  if (!tab) return null;
  section = document.createElement('section');
  section.id = 'content-library';
  section.setAttribute('aria-label', 'Content Library');
  section.innerHTML = `<div class="content-library-head"><strong>Content Library</strong><span class="content-library-count" id="content-library-count"></span></div>
    <div class="content-library-filters"><input type="search" id="content-library-search" placeholder="Search models and sounds…" aria-label="Search the Content Library">
    <select id="content-library-group" aria-label="Content Library category"><option value="">All models</option>${CONTENT_LIBRARY_GROUPS.map((g) => `<option value="${g.id}">${g.icon} ${escapeHtml(g.label)}</option>`).join('')}<option value="sounds">🔊 Sounds</option></select></div>
    <div id="content-library-list" class="content-library-list" role="list"></div>
    <p class="field-help" id="content-library-status">Ready-made models and sounds you can add to any project. Added items become project assets.</p>`;
  tab.prepend(section);
  section.querySelector('#content-library-search').addEventListener('input', renderContentLibrary);
  section.querySelector('#content-library-group').addEventListener('change', renderContentLibrary);
  section.querySelector('#content-library-list').addEventListener('click', (event) => {
    const button = event.target.closest('button[data-library-action]');
    if (!button) return;
    const key = button.dataset.libraryKey;
    if (button.dataset.libraryAction === 'model') addContentLibraryModel(key);
    else if (button.dataset.libraryAction === 'sound') addContentLibrarySound(key);
    else if (button.dataset.libraryAction === 'preview') previewContentLibrarySound(key);
  });
  return section;
}
function renderContentLibrary() {
  const section = ensureContentLibrarySection();
  if (!section) return;
  const list = section.querySelector('#content-library-list');
  if (!contentLibraryManifest) {
    list.innerHTML = '<p class="field-help">Loading library…</p>';
    loadContentLibraryManifest().then(renderContentLibrary, () => {
      list.innerHTML = '<p class="field-help">The Content Library is available in the hosted and development editor (it loads from the site, not from a standalone file).</p>';
    });
    return;
  }
  const query = section.querySelector('#content-library-search').value.trim().toLowerCase();
  const group = section.querySelector('#content-library-group').value;
  const matchesQuery = (key) => !query || key.replace(/-/g, ' ').includes(query) || key.includes(query);
  let html = '', count = 0;
  if (group !== 'sounds') {
    for (const model of contentLibraryManifest.meshes) {
      const modelGroup = contentLibraryGroup(model);
      if ((group && modelGroup.id !== group) || !matchesQuery(model.key)) continue;
      const inProject = !!findAssetById(model.id);
      html += `<div class="content-library-item" role="listitem"><span class="content-library-icon" aria-hidden="true">${modelGroup.icon}</span><span class="content-library-name">${escapeHtml(contentLibraryLabel(model.key))}${inProject ? ' <small>in project</small>' : ''}</span><button type="button" data-library-action="model" data-library-key="${escapeHtml(model.key)}" title="Add to the scene at the view centre">Add</button></div>`;
      count++;
    }
  }
  if (!group || group === 'sounds') {
    for (const sound of contentLibraryManifest.audio || []) {
      if (!matchesQuery(sound.key)) continue;
      html += `<div class="content-library-item" role="listitem"><span class="content-library-icon" aria-hidden="true">🔊</span><span class="content-library-name">${escapeHtml(contentLibraryLabel(sound.key))}</span><button type="button" data-library-action="preview" data-library-key="${escapeHtml(sound.key)}" aria-label="Preview ${escapeHtml(contentLibraryLabel(sound.key))}">▶</button><button type="button" data-library-action="sound" data-library-key="${escapeHtml(sound.key)}">Add</button></div>`;
      count++;
    }
  }
  list.innerHTML = html || '<p class="field-help">Nothing matches this search.</p>';
  section.querySelector('#content-library-count').textContent = count + (count === 1 ? ' item' : ' items');
}
(function mountContentLibrary() {
  if (window.__OPUS_EMBEDDED_PROJECT__) return; // standalone games have no library
  const tabButton = document.querySelector('[data-left-tab="assets"]');
  if (tabButton) tabButton.addEventListener('click', () => renderContentLibrary());
  ensureContentLibrarySection();
})();

// --- Start Blank: default player character ---
// The blank starter is playable immediately as a box; this swaps in the
// library's ranger character once it has loaded. Not an Undo step: it is part
// of the starter. A failed load keeps the box.
async function attachDefaultPlayerCharacter() {
  let prepared;
  try { prepared = await ensureContentLibraryModel('ranger'); } catch (error) { return false; }
  const level = levels[currentLevelIndex];
  if (playMode || !level || !level.playerSettings || level.playerSettings.controllerType !== 'thirdperson' || level.playerSettings.visual) return false;
  if (prepared.textureRecord) loadTextureAssets([prepared.textureRecord]);
  if (prepared.record) loadAssets([prepared.record]);
  level.playerSettings = { ...level.playerSettings, collisionHeight: 1.855, collisionRadius: 0.5,
    visual: { mode: 'skinned', assetId: 'showcase-ranger', textureAssetId: 'showcase-palette', scale: 1, positionOffset: { x: 0, y: -0.9275, z: 0 }, rotationOffsetY: 0,
      clipMap: { idle: 0, walk: 1, run: 2, jump: 3, fall: 4, attack: 5, death: 6 }, blendTime: 0.15, followBodyHeight: true } };
  applyLevelPlayerSettings(currentLevelIndex);
  if (typeof refreshAssetDiscovery === 'function') refreshAssetDiscovery();
  markProjectPristine();
  return true;
}
